#include "game/world12/inactive_roster_projection.hpp"
#include <algorithm>
#include <set>
namespace bmh::world12 {
const NationalStartupReceipt& inactive_population_receipt(const World& world){
    if(world.catalogue.scope.club_play()||!world.catalogue.scope.international||!world.national_origins||!world.national_coaches||!world.players_initialized||!world.free_players||!world.settings||world.transfer_market||world.economy||!world.loans.empty())throw FormatError("world12: actual unmanaged national population is unavailable");const NationalStartupReceipt* result=nullptr;for(const auto& actor:*world.national_coaches)if(actor.startup){if(result)throw FormatError("world12: national population receipt is ambiguous");result=&*actor.startup;}if(!result)throw FormatError("world12: national population receipt is unknown");return *result;
}
std::vector<ClubId> inactive_origin_order(const World& world){
    (void)inactive_population_receipt(world);const auto catalogue=Catalogue::dual_classic();std::vector<ClubId> result;
    for(auto group:{TableGroup::germany,TableGroup::england,TableGroup::europe})for(auto league:catalogue.simulation_leagues(group)){std::vector<const NationalRosterOrigin*> ordered;for(const auto& origin:*world.national_origins)if(origin.club.league==league)ordered.push_back(&origin);std::sort(ordered.begin(),ordered.end(),[](const auto* a,const auto* b){return a->rank<b->rank;});if(ordered.size()!=catalogue.league(league).clubs)throw FormatError("world12: inactive Source origin league is incomplete");for(size_t rank=0;rank<ordered.size();++rank){if(ordered[rank]->rank!=rank||!ordered[rank]->source_initialized)throw FormatError("world12: inactive Source origin order/initialization is unknown");result.push_back(ordered[rank]->club.id);}}
    return result;
}
uint16_t InactiveRosterProjection::local_player(PlayerId id)const{const auto at=std::find(players.begin(),players.end(),id);if(at==players.end())throw FormatError("world12: inactive Source player was not projected");return uint16_t(at-players.begin());}
PlayerId InactiveRosterProjection::global_player(uint16_t id)const{if(id>=players.size())throw FormatError("world12: inactive Source local player is invalid");return players[id];}
InactiveRosterProjection InactiveRosterProjection::create(const World& world,std::optional<ClubId> club,const GameState& reference,bool pools){
    world.validate();(void)inactive_population_receipt(world);InactiveRosterProjection result;result.club=club;result.state=reference;auto& state=result.state;state.manager_teams.clear();state.projected_match_clubs.clear();state.players.clear();state.player_cards.clear();state.player_bonus.clear();state.player_names.clear();state.player_name_offsets.clear();state.squad_slots.assign(size_t(runtime_dimensions.total_slots),0xfff);state.player_statistics.clear();state.club_names.assign(1,0);state.club_ids.assign(reference.club_ids.size(),0);state.club_kits.assign(reference.club_ids.size(),0);state.club_short_offsets.assign(reference.club_ids.size(),0);state.team_flags.assign(reference.team_flags.size(),0);state.team_morale.assign(reference.team_morale.size(),25);state.development_balance=world.development_balance;state.trend_rotation=world.trend_rotation;state.level=world.settings->difficulty;state.projected_foreign_rule=world.settings->foreign_rule;state.live_matches.clear();state.live_scene=false;state.last_shooter=0xfff;
    const auto add=[&](PlayerId id){if(!id.valid())return uint16_t(0xfff);const auto known=std::find(result.players.begin(),result.players.end(),id);if(known!=result.players.end())return uint16_t(known-result.players.begin());if(result.players.size()>=4095)throw FormatError("world12: inactive Source player workspace exceeded");const auto& player=world.players.at(id);if(state.player_names.size()+player.attributes.name.size()+1>65535)throw FormatError("world12: inactive Source name workspace exceeded");const auto local=uint16_t(result.players.size());result.players.push_back(id);state.players.push_back(player.attributes);state.player_cards.push_back(player.cards);state.player_bonus.push_back(player.bonus);state.player_name_offsets.push_back(uint16_t(state.player_names.size()));state.player_names.insert(state.player_names.end(),player.attributes.name.begin(),player.attributes.name.end());state.player_names.push_back(0);return local;};
    if(club){const auto found=std::find_if(world.national_origins->begin(),world.national_origins->end(),[&](const auto& origin){return origin.club.id==*club;});if(found==world.national_origins->end()||!found->source_initialized)throw FormatError("world12: actual inactive club origin is unavailable");const auto& record=found->club;const auto catalogue=Catalogue::dual_classic();const auto& league=catalogue.league(record.league);if(state.club_ids.empty()||state.team_flags.empty()||state.team_morale.empty())throw FormatError("world12: inactive Source club workspace is missing");state.club_ids[0]=1;state.club_names.insert(state.club_names.end(),record.name.begin(),record.name.end());state.club_names.push_back(0);state.club_kits[0]=record.kit;state.club_short_offsets[0]=record.short_span;state.team_flags[0]=record.match_flags;state.team_morale[0]=record.morale;const bool domestic=record.country==Country::germany||record.country==Country::england;const int semantic=domestic?league.local_index:record.country==Country::spain?5:record.country==Country::england?6:record.country==Country::france?7:8;state.projected_match_clubs.push_back({semantic,int(record.country),domestic?3:2});for(size_t row=0;row<24;++row)if(!record.roster[row].empty()){const auto& slot=record.roster[row];state.squad_slots[row]=uint16_t(add(slot.player)|((slot.flags&1)?0x8000:0)|((slot.flags&2)?0x4000:0)|((slot.flags&4)?0x2000:0)|((slot.flags&8)?0x1000:0));}}
    if(pools){const auto install=[&](const auto& pool,int first){for(size_t n=0;n<pool.size();++n)state.squad_slots.at(size_t(first)+n)=add(pool[n]);};install(world.free_players->domestic,runtime_dimensions.free_first);install(world.free_players->foreign,runtime_dimensions.foreign_free_first);}
    state.counts.players=uint32_t(state.players.size());return result;
}
void InactiveRosterProjection::capture(World& world,bool pools)const{
    (void)inactive_population_receipt(world);for(size_t n=0;n<players.size();++n){auto& player=world.players.at(players[n]);player.attributes=state.players.at(n);player.cards=state.player_cards.at(n);player.bonus=state.player_bonus.at(n);}
    if(club){auto found=std::find_if(world.national_origins->begin(),world.national_origins->end(),[&](const auto& origin){return origin.club.id==*club;});if(found==world.national_origins->end())throw FormatError("world12: inactive capture lost its actual club");for(size_t row=0;row<24;++row){const auto slot=state.squad_slots.at(row);found->club.roster[row]=(slot&0xfff)==0xfff?RosterSlot{}:RosterSlot{global_player(slot&0xfff),uint16_t(((slot&0x8000)?1:0)|((slot&0x4000)?2:0)|((slot&0x2000)?4:0)|((slot&0x1000)?8:0))};}found->club.match_flags=state.team_flags.at(0);found->club.morale=state.team_morale.at(0)&63;}
    if(pools){const auto capture=[&](auto& pool,int first){for(size_t n=0;n<pool.size();++n){const auto id=state.squad_slots.at(size_t(first)+n)&0xfff;pool[n]=id==0xfff?PlayerId{}:global_player(id);}};capture(world.free_players->domestic,runtime_dimensions.free_first);capture(world.free_players->foreign,runtime_dimensions.foreign_free_first);}
    world.development_balance=state.development_balance;if(state.trend_rotation<0||state.trend_rotation>2)throw FormatError("world12: inactive Source development rotation is invalid");world.trend_rotation=uint8_t(state.trend_rotation);
}
}
